import React, { useEffect, useState } from "react";
import axios from "axios";
import PageHeader from "./PageHeader";
import AlertBox from "./AlertBox";
import "./dashboard.css";

function Courses() {
  const userId = localStorage.getItem("user_id");
  const role = localStorage.getItem("role");

  const [courses, setCourses] = useState([]);
  const [alert, setAlert] = useState(null);

  const fetchCourses = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/courses");
      setCourses(res.data.courses || []);
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    fetchCourses();
  }, []);

  const handleEnroll = async (courseId) => {
    try {
      const res = await axios.post("http://127.0.0.1:8000/enroll", {
        user_id: parseInt(userId),
        course_id: courseId
      });

      setAlert({
        message: res.data.message,
        type: "success"
      });
    } catch (err) {
      console.error(err);
      setAlert({
        message: "Enrollment failed",
        type: "error"
      });
    }
  };

  return (
    <div>
      {alert && <AlertBox message={alert.message} type={alert.type} onClose={() => setAlert(null)} />}

      <PageHeader
        title="All Courses"
        subtitle="Browse all available courses with creator and created time."
      />

      <div className="grid-3">
        {courses.map((course) => (
          <div className="section-card" key={course.id}>
            <h4>{course.title}</h4>
            <div className="meta">{course.description}</div>
            <div className="meta">Subject Code: {course.subject_code}</div>
            <div className="meta">Created By: {course.created_by || "Unknown"}</div>
            <div className="meta">
              Created At: {course.created_at ? new Date(course.created_at).toLocaleString() : "N/A"}
            </div>

            {role === "student" && (
              <div style={{ marginTop: 14 }}>
                <button className="btn btn-primary" onClick={() => handleEnroll(course.id)}>
                  Enroll
                </button>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

export default Courses;
